import base64
import json
import os
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _load_bytes(source: Any) -> bytes:
    if source is None:
        raise ValueError("No document source provided.")

    if isinstance(source, bytes):
        return source

    if isinstance(source, str):
        if os.path.exists(source):
            with open(source, "rb") as f:
                return f.read()
        try:
            return base64.b64decode(source, validate=True)
        except Exception as e:
            raise ValueError("String source must be a valid file path or base64-encoded document.") from e

    if hasattr(source, "read"):
        data = source.read()
        if isinstance(data, str):
            return data.encode("utf-8")
        return data

    raise TypeError("Unsupported document source type.")


def _normalize_line_item(line_item: Dict[str, Any]) -> Dict[str, Any]:
    normalized = {
        "description": None,
        "quantity": None,
        "unit_price": None,
        "amount": None,
        "tax": None,
        "product_code": None,
    }

    for field in line_item.get("LineItemExpenseFields", []) or []:
        key = (field.get("Type", {}) or {}).get("Text", "")
        value = (field.get("ValueDetection", {}) or {}).get("Text")
        if not key:
            continue
        key_l = key.lower()
        if "item" in key_l and "description" in key_l:
            normalized["description"] = value
        elif "quantity" in key_l:
            normalized["quantity"] = value
        elif "unit" in key_l and ("price" in key_l or "rate" in key_l):
            normalized["unit_price"] = value
        elif key_l in {"amount", "total", "line total"} or "amount" in key_l or "total" in key_l:
            normalized["amount"] = value
        elif "tax" in key_l:
            normalized["tax"] = value
        elif "product" in key_l and "code" in key_l:
            normalized["product_code"] = value

    return normalized


def normalize_expense_fields(document_source: Any, region_name: str = "us-east-1") -> Dict[str, Any]:
    """
    Uses Amazon Textract AnalyzeExpense to extract and normalize expense data into a standard JSON schema.
    document_source can be a file path, bytes, base64 string, or file-like object.
    """
    document_bytes = _load_bytes(document_source)

    client = boto3.client("textract", region_name=region_name)

    try:
        response = client.analyze_expense(
            Document={"Bytes": document_bytes},
        )
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Textract AnalyzeExpense failed: {e}") from e

    expense_docs = response.get("ExpenseDocuments", []) or []
    normalized_expenses = []

    for expense_doc in expense_docs:
        doc_fields = {
            "vendor_name": None,
            "vendor_address": None,
            "invoice_receipt_id": None,
            "invoice_receipt_date": None,
            "due_date": None,
            "subtotal": None,
            "tax": None,
            "tip": None,
            "total": None,
            "currency": None,
            "payment_terms": None,
            "line_items": [],
        }

        for field in expense_doc.get("SummaryFields", []) or []:
            field_type = (field.get("Type", {}) or {}).get("Text", "")
            value = (field.get("ValueDetection", {}) or {}).get("Text")
            if not field_type:
                continue

            ft = field_type.lower()
            if ft in {"vendor_name", "supplier_name", "seller_name"}:
                doc_fields["vendor_name"] = value
            elif ft in {"vendor_address", "supplier_address", "seller_address"}:
                doc_fields["vendor_address"] = value
            elif ft in {"invoice_receipt_id", "invoice_id", "receipt_id", "document_number"}:
                doc_fields["invoice_receipt_id"] = value
            elif ft in {"invoice_receipt_date", "invoice_date", "receipt_date", "date"}:
                doc_fields["invoice_receipt_date"] = value
            elif ft in {"due_date"}:
                doc_fields["due_date"] = value
            elif ft in {"subtotal", "sub_total"}:
                doc_fields["subtotal"] = value
            elif ft in {"tax", "tax_amount"}:
                doc_fields["tax"] = value
            elif ft in {"tip", "gratuity"}:
                doc_fields["tip"] = value
            elif ft in {"total", "amount_due", "grand_total", "balance_due"}:
                doc_fields["total"] = value
            elif ft in {"currency", "currency_code"}:
                doc_fields["currency"] = value
            elif ft in {"payment_terms", "terms"}:
                doc_fields["payment_terms"] = value

        for line_item_group in expense_doc.get("LineItemGroups", []) or []:
            for line_item in line_item_group.get("LineItems", []) or []:
                doc_fields["line_items"].append(_normalize_line_item(line_item))

        normalized_expenses.append(doc_fields)

    return {
        "provider": "amazon-textract",
        "schema_version": "1.0",
        "expenses": normalized_expenses,
        "raw": response,
    }


def normalize_expense_fields_json(document_source: Any, region_name: str = "us-east-1") -> str:
    return json.dumps(normalize_expense_fields(document_source, region_name=region_name), ensure_ascii=False, default=str)
